const input = $input.first()?.json || {};
const body = input.body;

function fail(message) {
  throw new Error(`VALIDATION_ERROR: ${message}`);
}

function codePointLength(value) {
  return [...value].length;
}

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  fail('请求体必须是 JSON 对象');
}
if (typeof body.content !== 'string') {
  fail('content 必须是字符串');
}
const content = body.content.trim().replace(/[ \t]+/g, ' ');
if (!content) {
  fail('content 不能为空');
}
if (/[\r\n]/.test(content)) {
  fail('content 必须是单行文本');
}
if (codePointLength(content) > 1000) {
  fail('content 最多 1000 个 Unicode 字符');
}
if (typeof body.language !== 'string') {
  fail('language 必须是字符串');
}
const language = body.language.trim().replace(/[ \t]+/g, ' ');
if (!language) {
  fail('language 不能为空');
}
if (/[\r\n]/.test(language) || codePointLength(language) > 64) {
  fail('language 必须是最多 64 个 Unicode 字符的单行文本');
}
const maxLength = Number(body.maxLength);
if (!Number.isInteger(maxLength) || maxLength < 1 || maxLength > 60) {
  fail('maxLength 必须是 1 到 60 的整数');
}
let requestId = '';
if (body.requestId !== undefined && body.requestId !== null) {
  if (typeof body.requestId !== 'string') {
    fail('requestId 必须是字符串');
  }
  requestId = body.requestId.trim();
  if (!requestId || /[\r\n]/.test(requestId) || codePointLength(requestId) > 128) {
    fail('requestId 必须是最多 128 个 Unicode 字符的非空单行文本');
  }
}

const sysPrompt = [
  '你是一名专业的多语言电商标题翻译助手。',
  '准确、自然地把原文翻译为用户指定语言；保留核心品类、性别、款式和用途信息，不得添加原文没有的品牌、材质、功能或承诺。',
  '翻译标题必须是单行文本，不得包含回车、换行、Markdown、解释、前后缀或引号。',
  'contentTranslate 的 Unicode 字符总数不得超过 maxLength；必要时在不丢失核心品类的前提下精简。',
  '必须只输出一个合法 JSON 对象。由于调用方 S007 要求外层字段 messageContent，messageContent 必须是一个 JSON 字符串，该字符串解析后只能包含字符串字段 contentTranslate。',
  '外层格式必须精确类似：{"messageContent":"{\"contentTranslate\":\"翻译结果\"}"}。禁止输出代码块或任何额外内容。',
].join('\n');
const userPrompt = `请翻译以下 JSON 数据中的 content，并严格遵守 language 和 maxLength：\n${JSON.stringify({ content, language, maxLength })}`;

return [{ json: {
  content,
  language,
  maxLength,
  requestId,
  sysPrompt,
  userPrompt,
} }];

const response = $input.first()?.json || {};
const request = $('Validate Translation Request').first()?.json || {};
const raw = response.messageContent;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('S007 未返回非空字符串 messageContent');
}
let parsed;
try {
  parsed = JSON.parse(raw.trim());
} catch (_) {
  throw new Error('S007 messageContent 不是合法的 contentTranslate JSON');
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  throw new Error('翻译结果必须是 JSON 对象');
}
const keys = Object.keys(parsed);
if (keys.length !== 1 || keys[0] !== 'contentTranslate' || typeof parsed.contentTranslate !== 'string') {
  throw new Error('翻译结果必须且只能包含字符串字段 contentTranslate');
}
const contentTranslate = parsed.contentTranslate.trim().replace(/[ \t]+/g, ' ');
if (!contentTranslate) {
  throw new Error('contentTranslate 不能为空');
}
if (/[\r\n]/.test(contentTranslate)) {
  throw new Error('contentTranslate 必须是单行文本');
}
const translatedLength = [...contentTranslate].length;
if (translatedLength > Number(request.maxLength)) {
  throw new Error(`contentTranslate 长度 ${translatedLength} 超过 maxLength ${request.maxLength}`);
}

return [{ json: {
  contentTranslate,
  model: response.model || null,
  usage: response.usage || null,
  finishReason: response.finishReason || null,
  requestId: request.requestId || null,
  translatedLength,
} }];

const input = $input.first()?.json || {};
const rawMessage = String(input.error?.message || input.error || input.message || '请求参数无效');
const message = rawMessage
  .replace(/^VALIDATION_ERROR:\s*/, '')
  .replace(/\s*\[line \d+\]\s*$/, '')
  .trim() || '请求参数无效';
let requestId = null;
try {
  const candidate = $('Translation Title Webhook').first()?.json?.body?.requestId;
  if (typeof candidate === 'string' && candidate.trim()) requestId = candidate.trim();
} catch (_) {}
return [{ json: {
  error: 'VALIDATION_ERROR',
  message,
  requestId,
  httpStatus: 400,
} }];

const input = $input.first()?.json || {};
const rawMessage = String(input.error?.message || input.error || input.message || '标题翻译失败');
let requestId = null;
try { requestId = $('Validate Translation Request').first()?.json?.requestId || null; } catch (_) {}
return [{ json: {
  error: 'TRANSLATION_FAILED',
  message: '标题翻译服务暂时不可用，请稍后重试',
  requestId,
  httpStatus: 502,
  auditMessage: rawMessage.slice(0, 500),
} }];
